INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Markterkundung immer nur für neue Produkte gemacht wird. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für bestehende Produkte"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich eine Markterkundung für eine IT-Firma plane?', 3, '[{"text": "Zielmarktanalyse", "correct": true, "because": "Bestimmt Potenzial"}, {"text": "Schnellste Durchführung", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Bürodesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur Markterkundung in der IT?', 5, '[{"text": "Kundenbedürfnisse", "correct": true, "because": "Bestimmen Nachfrage"}, {"text": "Wettbewerber", "correct": true, "because": "Zeigen Marktposition"}, {"text": "Büromöbel", "correct": false, "because": "Kein Marktfaktor"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Markterkundung hilft Potenziale zu erkennen. b) Sie ist immer teuer.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten variieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich eine Markterkundung für eine IT-Firma durchführe?', 4, '[{"text": "Markttrends", "correct": false, "because": "Beeinflussen Strategie"}, {"text": "Kundensegmente", "correct": false, "because": "Bestimmen Zielgruppe"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Marktfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Markterkundung nur für große Märkte relevant ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Märkte wichtig"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Markterkundung in der IT?', 3, '[{"text": "Marktchancen erkennen", "correct": true, "because": "Fördert Strategie"}, {"text": "Schnellste Analyse", "correct": false, "because": "Qualität zählt"}, {"text": "Weniger Daten", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden nutzt die Markterkundung in der IT?', 5, '[{"text": "Umfragen", "correct": true, "because": "Erfassen Bedürfnisse"}, {"text": "Wettbewerbsvergleich", "correct": true, "because": "Analysiert Markt"}, {"text": "Büroplanung", "correct": false, "because": "Irrelevant"}, {"text": "Farbanalyse", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Markterkundung identifiziert Kundenbedürfnisse. b) Sie ist nur für Großfirmen nützlich. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch KMU profitieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Markterkundung in der IT?', 4, '[{"text": "Marktdaten", "correct": false, "because": "Liefern Informationen"}, {"text": "Kundenfeedback", "correct": false, "because": "Zeigt Bedarf"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Marktfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Markterkundung dasselbe wie Marktbeobachtung?', 2, '[{"text": "Nein", "correct": true, "because": "Einmalig vs. kontinuierlich"}, {"text": "Ja", "correct": false, "because": "Verschiedene Ansätze"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Markterkundung in der IT?', 4, '[{"text": "Wettbewerbsvorteil", "correct": true, "because": "Erkennt Chancen"}, {"text": "Marktanpassung", "correct": true, "because": "Passt Angebote an"}, {"text": "Schnellere Projekte", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Markterkundung nur für neue Märkte gilt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch bestehende Märkte"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um Markterkundung für eine IT-Firma durchzuführen?', 3, '[{"text": "Kundenbefragungen", "correct": true, "because": "Liefert Daten"}, {"text": "Schnellste Software", "correct": false, "because": "Genauigkeit wichtiger"}, {"text": "Bunte Diagramme", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Markterkundung analysiert Wettbewerber. b) Sie ist immer teuer.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten variieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei Markterkundung in der IT?', 5, '[{"text": "Marktpotenziale", "correct": true, "because": "Zeigen Chancen"}, {"text": "Kundenpräferenzen", "correct": true, "because": "Steuern Angebot"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich Markterkundung für eine IT-Firma plane?', 3, '[{"text": "Marktdaten", "correct": false, "because": "Liefern Informationen"}, {"text": "Konkurrenzanalyse", "correct": false, "because": "Zeigt Position"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Marktfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Markterkundung nur für große IT-Firmen relevant?', 3, '[{"text": "Nein", "correct": true, "because": "Auch KMU profitieren"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
